def mass(A):
    return sum(abs(v) for P in A for v in P.values())

def sparse(A):
    half = rational(1, 2)
    orbits = {}
    for P in A:
        for w in P:
            if len(w) <= 4 and 2 * sum(f for f, m in w) == len(w):
                t = tuple((1, m) for f, m in w if f == 0) + tuple((0, m) for f, m in w if f == 1)
                u = min(w, t)
                if u not in orbits:
                    v = max(w, t)
                    re = (A[0].get(u, 0) + A[0].get(v, 0)) * half
                    im = (A[1].get(u, 0) - A[1].get(v, 0)) * half
                    score = (abs(re) + abs(im)) * (1 if u == v else 2)
                    if score:
                        orbits[u] = (score, u, v, re, im)
    R = ({}, {})
    for score, u, v, re, im in sorted(orbits.values(), reverse=True)[:2048]:
        if re:
            R[0][u] = re
            R[0][v] = re
        if im:
            R[1][u] = im
            R[1][v] = -im
    return R

def remainder(A, basis):
    coeffs, residual = coordinates(A, basis)
    R = ({}, {})
    if residual:
        R = A
        for B, c in zip(basis, coeffs):
            if c:
                R = cadd(R, cscale(B, -c))
    return R

def propose(payload):
    one = rational(1, 1)
    half = rational(1, 2)
    limit = min(14, payload.get('max_additional_observables', 14))
    basis = [({(): one}, {}), payload['D']]
    answer = []
    unit = mass(payload['D'])
    if not unit:
        unit = one
    for name in ('W', 'Y'):
        A = sparse(payload[name])
        if len(answer) < limit and mass(A):
            coeffs, residual = coordinates(A, basis)
            if residual:
                A = cscale(A, unit / mass(A))
                basis.append(A)
                answer.append(A)
    generators = [(payload['H'], one), (payload['D'], half), (payload['W'], half)]
    frontier = []
    expanded = 1
    budget = 2000000
    running = True
    while len(answer) < limit and running:
        while expanded < len(basis):
            O = basis[expanded]
            size = len(O[0]) + len(O[1])
            for G, weight in generators:
                cost = size * (len(G[0]) + len(G[1]))
                if cost and cost <= min(budget, 250000):
                    budget = budget - cost
                    A = sparse(drift(G, O))
                    if mass(A):
                        frontier.append((A, weight))
            expanded = expanded + 1
        best = -1
        bestscore = 0
        chosen = ({}, {})
        for j, item in enumerate(frontier):
            A, weight = item
            R = sparse(remainder(A, basis))
            size = mass(R)
            score = weight * size
            if score > bestscore and size <= 4 * mass(A):
                coeffs, residual = coordinates(R, basis)
                if residual:
                    best = j
                    bestscore = score
                    chosen = R
        if best < 0:
            running = False
        else:
            frontier.pop(best)
            chosen = cscale(chosen, unit / mass(chosen))
            basis.append(chosen)
            answer.append(chosen)
    if not answer:
        for m in range(payload['modes']):
            if not answer:
                A = ({((1, m), (0, m)): one}, {})
                coeffs, residual = coordinates(A, basis)
                if residual:
                    answer.append(A)
    return answer
